require_once __DIR__ . "/../config/auth.php";
require_once __DIR__ . "/../config/db.php";
require_once __DIR__ . "/../config/helpers.php";

$customers = $pdo->query("SELECT makhachhang, hoten, sodienthoai FROM khachhang ORDER BY makhachhang DESC")->fetchAll();
$selectedCarId = (int)($_GET['maxe'] ?? 0);
$carsReady = $pdo->query("SELECT maxe, hangxe, dongxe, bienso, giaban_dukien, hinhanh FROM xe WHERE trangthai='READY' ORDER BY maxe DESC")->fetchAll();
$depositedRows = $pdo->query("SELECT p.maphieuban, p.maxe, p.giaban_chot, p.tiencoc_ban, p.hinhthucthanhtoan, x.hangxe, x.dongxe, x.bienso, k.hoten AS tenkhach FROM phieuban p JOIN xe x ON x.maxe = p.maxe JOIN khachhang k ON k.makhachhang = p.makhachhang WHERE p.trangthai_giaodich='DEPOSITED' ORDER BY p.maphieuban DESC")->fetchAll();
$rows = $pdo->query("SELECT p.*, x.hangxe, x.dongxe, x.bienso, k.hoten AS tenkhach, n.hoten AS tennv FROM phieuban p JOIN xe x ON x.maxe = p.maxe JOIN khachhang k ON k.makhachhang = p.makhachhang LEFT JOIN nhanvien n ON n.manhanvien = p.manhanvien ORDER BY p.maphieuban DESC")->fetchAll();
$statusLabels = ['DEPOSITED' => 'Đã cọc','PAID' => 'Đã thanh toán','SOLD' => 'Đã bán','CANCEL' => 'Đã hủy'];
$paymentLabels = ['cash' => 'Tiền mặt', 'bank' => 'Chuyển khoản', 'loan' => 'Trả góp'];
$statusClasses = ['DEPOSITED'=>'status-deposited','PAID'=>'status-ready','SOLD'=>'status-sold','CANCEL'=>'status-cancel'];
$title = 'Giao dịch'; require_once __DIR__ . '/../partials/header.php'; ?>
<div class="page-header"><div><h1 class="page-title">Quản lý giao dịch</h1><p class="page-subtitle">Thực hiện đặt cọc, xác nhận bán và theo dõi toàn bộ phiếu giao dịch.</p></div></div>
<div class="quick-grid"><div class="stat-tile"><small>Xe sẵn sàng bán</small><b><?= count($carsReady) ?></b></div><div class="stat-tile"><small>Phiếu đang cọc</small><b><?= count($depositedRows) ?></b></div><div class="stat-tile"><small>Tổng giao dịch</small><b><?= count($rows) ?></b></div><div class="stat-tile"><small>Khách hàng có thể giao dịch</small><b><?= count($customers) ?></b></div></div>
<div class="row g-4">
  <div class="col-lg-6"><div class="card form-card h-100" id="deposit-form"><h5 class="mb-3">Tạo phiếu đặt cọc</h5><form method="post" action="<?= url('transactions/save_deposit.php') ?>"><div class="row g-3"><div class="col-12"><label class="form-label">Khách hàng</label><select class="form-select" name="makhachhang" required><option value="">Chọn khách hàng</option><?php foreach($customers as $c): ?><option value="<?= (int)$c['makhachhang'] ?>"><?= e($c['hoten'].' - '.$c['sodienthoai']) ?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">Xe (READY)</label><select class="form-select" name="maxe" required><option value="">Chọn xe</option><?php foreach($carsReady as $x): ?><option value="<?= (int)$x['maxe'] ?>" <?= $selectedCarId === (int)$x['maxe'] ? 'selected' : '' ?>><?= e($x['hangxe'].' '.$x['dongxe'].' - '.$x['bienso'].' - '.money($x['giaban_dukien'])) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Giá bán chốt</label><input class="form-control" name="giaban_chot" type="number" step="0.01" placeholder="VD: 780000000"></div><div class="col-md-6"><label class="form-label">Tiền cọc *</label><input class="form-control" name="tiencoc_ban" type="number" step="0.01" required placeholder="VD: 50000000"></div><div class="col-12"><label class="form-label">Hình thức thanh toán</label><select class="form-select" name="hinhthucthanhtoan"><option value="cash">Tiền mặt</option><option value="bank">Chuyển khoản</option><option value="loan">Trả góp</option></select></div></div><button class="btn btn-primary w-100 mt-3">Tạo phiếu cọc</button></form></div></div>
  <div class="col-lg-6"><div class="card form-card h-100"><h5 class="mb-3">Xác nhận bán xe</h5><form method="post" action="<?= url('transactions/save_sale.php') ?>"><div class="row g-3"><div class="col-12"><label class="form-label">Phiếu bán (đang ĐÃ CỌC)</label><select class="form-select" name="maphieuban" required><option value="">Chọn phiếu bán</option><?php foreach($depositedRows as $p): ?><option value="<?= (int)$p['maphieuban'] ?>">Mã <?= (int)$p['maphieuban'] ?> • <?= e($p['hangxe'].' '.$p['dongxe'].' • '.$p['bienso'].' • KH: '.$p['tenkhach']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Giá bán chốt *</label><input class="form-control" name="giaban_chot" type="number" step="0.01" required placeholder="VD: 780000000"></div><div class="col-md-6"><label class="form-label">Hình thức thanh toán</label><select class="form-select" name="hinhthucthanhtoan"><option value="cash">Tiền mặt</option><option value="bank">Chuyển khoản</option><option value="loan">Trả góp</option></select></div><div class="col-md-6"><label class="form-label">Trạng thái vay</label><select class="form-select" name="trangthaivay"><option value="">Không áp dụng</option><option value="PENDING">Đang chờ duyệt</option><option value="APPROVED">Đã duyệt</option><option value="REJECTED">Từ chối</option></select></div><div class="col-md-6"><label class="form-label">Ghi chú bàn giao</label><input class="form-control" name="noidungbangiao" placeholder="VD: 2 chìa, đăng kiểm, cavet..."></div></div><button class="btn btn-success w-100 mt-3">Xác nhận bán</button></form><div class="small text-muted mt-2">* Hệ thống chuyển xe sang <b>Đã bán</b>, tạo giao dịch tài chính và biên bản bàn giao nếu có ghi chú.</div></div></div>
</div>
<div class="my-4"></div>
<div class="page-header mt-2"><div><h2 class="page-title" style="font-size:1.25rem;">Danh sách phiếu bán</h2><p class="page-subtitle">Theo dõi toàn bộ phiếu đặt cọc và phiếu bán đã phát sinh.</p></div></div>
<div class="table-responsive"><table class="table align-middle"><thead><tr><th>Mã</th><th>Xe</th><th>Khách</th><th>NV</th><th>Giá bán</th><th>Cọc</th><th>Thanh toán</th><th>Trạng thái</th><th>Ngày</th><th class="text-end">In hóa đơn</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= (int)$r['maphieuban']; ?></td><td><?= e($r['hangxe']." ".$r['dongxe']." - ".$r['bienso']); ?></td><td><?= e($r['tenkhach']); ?></td><td><?= e($r['tennv']); ?></td><td><?= money($r['giaban_chot']); ?></td><td><?= money($r['tiencoc_ban']); ?></td><td><?= e($paymentLabels[$r['hinhthucthanhtoan']] ?? $r['hinhthucthanhtoan']); ?></td><td><span class="status-badge <?= $statusClasses[$r['trangthai_giaodich']] ?? 'status-new' ?>"><?= e($statusLabels[$r['trangthai_giaodich']] ?? $r['trangthai_giaodich']); ?></span></td><td><?= e($r['ngaytao']); ?></td><td class="text-end"><div class="btn-group invoice-actions" role="group"><?php if ($r['trangthai_giaodich'] === 'DEPOSITED'): ?><a class="btn btn-sm btn-outline-primary" target="_blank" href="<?= url('transactions/invoice_deposit.php?id='.(int)$r['maphieuban']) ?>">Phiếu cọc</a><a class="btn btn-sm btn-outline-dark" target="_blank" href="<?= url('transactions/invoice_receipt.php?id='.(int)$r['maphieuban'].'&type=deposit') ?>">Phiếu thu</a><?php elseif ($r['trangthai_giaodich'] === 'SOLD'): ?><a class="btn btn-sm btn-outline-success" target="_blank" href="<?= url('transactions/invoice_sale.php?id='.(int)$r['maphieuban']) ?>">Hóa đơn bán</a><a class="btn btn-sm btn-outline-dark" target="_blank" href="<?= url('transactions/invoice_receipt.php?id='.(int)$r['maphieuban'].'&type=sale') ?>">Phiếu thu</a><?php else: ?><span class="text-muted small">—</span><?php endif; ?></div></td></tr><?php endforeach; ?><?php if (empty($rows)): ?><tr><td colspan="10"><div class="empty-state"><div class="empty-icon"><i class="bi bi-receipt-cutoff"></i></div><div>Chưa có giao dịch</div></div></td></tr><?php endif; ?></tbody></table></div>
